package org.animallink.gateway;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import org.springframework.http.HttpMethod;
class AdoptionMiniappGatewayPolicyTest {
 @Test void limitsUserScope(){String root="/auth/wechat/adoption",id="00000000-0000-4000-8000-000000000001";assertTrue(ExternalIdentityBoundaryFilter.isAuthenticationEndpoint(HttpMethod.POST,root+"/listings/"+id+"/applications"));assertTrue(AdoptionMiniappGatewayPolicy.allowed("GET",root+"/applications"));assertTrue(AdoptionMiniappGatewayPolicy.allowed("GET",root+"/handovers"));assertEquals("adoption.handover.read",AdoptionMiniappGatewayPolicy.scope("GET",root+"/handovers"));assertFalse(AdoptionMiniappGatewayPolicy.allowed("POST",root+"/handovers"));assertTrue(AdoptionMiniappGatewayPolicy.allowed("POST",root+"/applications/"+id+"/withdraw"));assertFalse(AdoptionMiniappGatewayPolicy.allowed("POST",root+"/governance/applications/"+id+"/approve"));assertTrue(ExternalIdentityBoundaryFilter.isPublicRead(HttpMethod.GET,"/adoption/api/v1/public/listings"));assertFalse(ExternalIdentityBoundaryFilter.isPublicRead(HttpMethod.POST,"/adoption/api/v1/public/listings"));}
}
